function isRuinsScreen(){return screen==='ruins-select'||screen==='ruins-play'||screen==='ruins-p2p-lobby';}
function primeVisibleSafe(c){try{return typeof primeCharacterVisible==='function'?primeCharacterVisible(c):!c?.codeOnly||state?.roster?.includes(c.id)}catch(_){return !c?.codeOnly}}
function isPrimeId(id){try{return Array.isArray(PRIME_SECRET_IDS)&&PRIME_SECRET_IDS.includes(id)}catch(_){return ['ktrak','jone','laranja'].includes(id)}}
function isLegendId(id){try{return (Array.isArray(STORY_LEGENDS)&&STORY_LEGENDS.includes(id))||['priya','kain','aria','leo','tharoth'].includes(id)}catch(_){return ['priya','kain','aria','leo','tharoth'].includes(id)}}
function categoryOf(c){if(c?.id==='ztaaa')return'BOSS';if(isPrimeId(c.id))return'PRIME';if(isLegendId(c.id)||c.id==='frogh')return'LENDA';return'CAMPEÃO'}
function ravamCharacters(){try{return Array.from(window.RavamStudios?.characters||[])}catch(_){return[]}}
function ravamOwned(c){try{return !!window.RavamStudios?.isOwned?.(c.id)}catch(_){return false}}
function mergeChars(...groups){const m=new Map();for(const g of groups)for(const c of (g||[]))if(c?.id&&!m.has(c.id))m.set(c.id,c);return[...m.values()]}
function selectableRuinsFighters(){
  const normal=(typeof CHARACTERS!=='undefined'?CHARACTERS:[]).filter(c=>c.id!=='rojo'&&(c.id!=='ztaaa'||!!state.ztaaaUnlocked)&&state.roster.includes(c.id)&&primeVisibleSafe(c));
  const legends=ravamCharacters().filter(c=>c.id!=='rojo'&&c.id!=='ztaaa'&&ravamOwned(c)&&primeVisibleSafe(c));
  return mergeChars(normal,legends);
}
function enemyPool(){
  const normal=(typeof CHARACTERS!=='undefined'?CHARACTERS:[]).filter(c=>c.id!=='rojo'&&c.id!=='ztaaa'&&c.id!=='frogh'&&primeVisibleSafe(c));
  const legends=ravamCharacters().filter(c=>c.id!=='rojo'&&c.id!=='ztaaa'&&!isPrimeId(c.id)&&!!state.ravamModeUnlocked);
  const primes=ravamCharacters().filter(c=>isPrimeId(c.id)&&primeVisibleSafe(c)&&ravamOwned(c));
  return mergeChars(normal,legends,primes).filter(c=>c.id!==ruinsGame?.selected?.id);
}
function charById(id){return mergeChars(typeof CHARACTERS!=='undefined'?CHARACTERS:[],ravamCharacters()).find(c=>c.id===id)||null}
function shuffle(a){const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function abilitySafe(c){try{return abilityOf(c)||{role:'Lutador'}}catch(_){return{role:'Lutador'}}}
function injectRuinsModeCard(){
  if(screen!=='modes')return;const grid=document.querySelector('.mode-grid.mk-modes,.mode-grid');if(!grid||document.getElementById('mode-ruins'))return;
  const b=document.createElement('button');b.id='mode-ruins';b.className='mode-card mk-mode ruins-mode-card';
  b.innerHTML='<div class="mode-icon">🏚️</div><span class="ruins-badge">EXPEDIÇÃO 2.5D · V21</span><h3>RUÍNAS</h3><p>Uma campanha longa em 12 setores, com IA tática, suprimentos, cronopausa e a batalha final para libertar Rojo.</p>';
  const boss=document.getElementById('mode-boss');if(boss)grid.insertBefore(b,boss);else grid.appendChild(b);b.onclick=()=>{try{SFX.play('menu_confirm')}catch(_){}renderRuinsSelect()};
}
function stopRuins(){if(ruinsGame?.raf)cancelAnimationFrame(ruinsGame.raf);ruinsGame=null;keys.clear();document.body.classList.remove('ruins-active');document.querySelector('.ruins-complete')?.remove();document.querySelector('.ruins-failed')?.remove()}
function closeRuinsNetwork(){if(!ruinsNet)return;try{ruinsNet.connections?.forEach(e=>{try{e.fast?.close()}catch(_){}try{e.conn?.close()}catch(_){}})}catch(_){}try{ruinsNet.fast?.close()}catch(_){}try{ruinsNet.conn?.close()}catch(_){}try{ruinsNet.peer?.destroy()}catch(_){}ruinsNet=null}
