function fighterCard(c){const a=abilitySafe(c),cat=categoryOf(c);return`<button class="ruins-fighter" data-id="${c.id}" style="--rc:${c.color}"><div class="rf-class">${cat}</div><div class="rf-name">${c.name}</div><div class="rf-role">${a.role||'Lutador'}</div><div class="rf-stats"><span>⚡ ${c.speed}</span><span>💥 ${c.dmg}</span><span>❤ ${c.hp}</span></div><div class="rf-power">J · ${POWER_LABELS[c.id]||'PODER'}</div><div class="rf-mark">${cat==='PRIME'?'P':cat==='LENDA'?'L':'C'}</div></button>`}
