function ruinsSyncActor(pack,existing,playerIndex=0){if(!pack)return null;let a=existing;if(!a){const c=charById(pack.id);if(!c)return null;a=makeActor(c,{player:!!pack.player,boss:!!pack.boss,playerIndex:pack.playerIndex||playerIndex||1})}const keepVisual=a.visual,keepChar=a.char,oldX=a.x,oldLane=a.lane,oldZ=a.z;for(const k of RUINS_SYNC_FIELDS)if(k in pack&& !['x','lane','z'].includes(k))a[k]=pack[k];a.char=keepChar||charById(pack.id);a.visual=keepVisual||makeVisual(a.char,!!pack.player,pack.playerIndex===2?'p2':'p1');a.status=pack.status||{};a.sequence=pack.sequence||null;a.proMove=pack.proMove||null;a.netX=pack.x;a.netLane=pack.lane;a.netZ=pack.z;if(!Number.isFinite(oldX)){a.x=pack.x;a.lane=pack.lane;a.z=pack.z}else{a.x=oldX;a.lane=oldLane;a.z=oldZ}return a}
function ruinsApplySnapshot(s){const g=ruinsGame;if(!g||g.authoritative||!s)return;g.phase=s.phase;g.wave=s.wave;g.streetOffset=s.streetOffset;g.advanceProgress=s.advanceProgress;g.banner=s.banner;g.bannerSub=s.bannerSub;g.bannerT=s.bannerT;g.notice=s.notice;g.noticeT=s.noticeT;g.enemyTimeStop=s.enemyTimeStop;g.difficulty=s.difficulty;g.battleLock=s.battleLock;g.bossPhase=s.bossPhase;g.checkpoint=s.checkpoint;g.prisonOpen=s.prisonOpen;g.rojoWalk=s.rojoWalk;g.rojoFreed=s.rojoFreed;g.freedomStep=s.freedomStep;g.complete=s.complete;
  const p1=ruinsSyncActor(s.players?.[0],g.player,1),p2=ruinsSyncActor(s.players?.[1],g.p2,2);g.player=p1;g.p2=p2;g.players=[p1,p2].filter(Boolean);g.coop=!!p2;const old=new Map((g.enemies||[]).map(a=>[a.netId,a]));g.enemies=(s.enemies||[]).map(x=>ruinsSyncActor(x,old.get(x.netId),0)).filter(Boolean);g.boss=s.boss?ruinsSyncActor(s.boss,g.boss,0):null;const all=[...g.players,...g.enemies,g.boss].filter(Boolean),byId=new Map(all.map(a=>[a.netId,a]));const unpack=o=>{const x={...o};x.owner=byId.get(o.ownerNetId)||null;x.target=byId.get(o.targetNetId)||null;x.hitSet=new Set();delete x.ownerNetId;delete x.targetNetId;return x};g.projectiles=(s.projectiles||[]).map(unpack);g.areas=(s.areas||[]).map(unpack);g.props=(s.props||[]).map(x=>({...x}));g.items=(s.items||[]).map(x=>({...x}));g.hazards=(s.hazards||[]).map(x=>({...x}));g.fx=(s.fx||[]).map(x=>({...x}));g.confetti=(s.confetti||[]).map(x=>({...x}));refreshHud()}
function ruinsClientStep(dt){const g=ruinsGame;if(!g||g.authoritative)return;if(ruinsNet?.pendingState){const s=ruinsNet.pendingState;ruinsNet.pendingState=null;ruinsApplySnapshot(s)}const local=g.players.find(p=>p.playerIndex===2);for(const a of [...g.players,...g.enemies,g.boss].filter(Boolean)){const k=a===local?.14:.18;if(Number.isFinite(a.netX)){a.x+=(a.netX-a.x)*Math.min(1,dt*60*k);a.lane+=(a.netLane-a.lane)*Math.min(1,dt*60*k);a.z+=(a.netZ-a.z)*Math.min(1,dt*60*k)}}if(local&&!local.downed&&local.hurtT<=0&&local.downT<=0){const inp=ruinsLocalInput();let dx=(inp.right?1:0)-(inp.left?1:0),dy=(inp.down?1:0)-(inp.up?1:0);if(dx&&dy){dx*=Math.SQRT1_2;dy*=Math.SQRT1_2}const sp=local.speed*(local.onGround?1:.82);local.x=clamp(local.x+dx*sp*dt,60,W-60);local.lane=clamp(local.lane+dy*.58*dt,LANE_MIN,LANE_MAX);if(dx)local.facing=Math.sign(dx)}g.bannerT=Math.max(0,(g.bannerT||0)-dt);g.noticeT=Math.max(0,(g.noticeT||0)-dt)}
function grantRuinsReward(token,reward=REWARD){if(!token)return false;if(!Array.isArray(state.ruinsP2PRewardTokens))state.ruinsP2PRewardTokens=[];if(state.ruinsP2PRewardTokens.includes(token))return false;state.ruinsP2PRewardTokens.push(token);state.ruinsP2PRewardTokens=state.ruinsP2PRewardTokens.slice(-20);state.coins=Math.max(0,Number(state.coins)||0)+Number(reward.gold||0);state.vandais=Math.max(0,Number(state.vandais)||0)+Number(reward.vandais||0);state.psy=Math.max(0,Number(state.psy)||0)+Number(reward.psy||0);state.ruinsRojoFreed=true;state.ruinsCompletions=(Number(state.ruinsCompletions)||0)+1;persist();return true}

function realFightStats(c,human=true){const rawHp=c.id==='ztaaa'?3600:(c.hp||1200),forceFactor=1+Math.max(0,(c.dmg||30)-28)*.012;return{hp:Math.round(rawHp*2.2*forceFactor),dmg:Math.round((c.dmg||30)*1.5)*(human?1:1.06),speed:150+(c.speed||70)}}
