  ctx.fillStyle=walkCol;ctx.beginPath();ctx.moveTo(0,350);ctx.lineTo(235,vanY);ctx.lineTo(128,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(W-235,vanY);ctx.lineTo(W,350);ctx.lineTo(W,H);ctx.lineTo(W-128,H);ctx.closePath();ctx.fill();
  ctx.strokeStyle=theme==='toxic'?'#697b35':'#a18b68';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(235,vanY);ctx.lineTo(128,H);ctx.moveTo(W-235,vanY);ctx.lineTo(W-128,H);ctx.stroke();
