function syncVisual(a){const v=a.visual;if(!v)return;v.id=a.copyT>0&&['frogh','klopp'].includes(a.id)&&a.copyId?a.copyId:a.id;const copied=charById(v.id);if(copied){v.name=copied.name;v.color=copied.color;v.weapon=copied.weapon;v.special=copied.special}v.x=0;v.y=Math.max(0,a.z||0);v.vy=-(a.vz||0);v.onGround=!!a.onGround;v.facing=a.facing||1;v.defend=a.guard;v.hp=a.hp;v.maxHp=a.maxHp;v.speed=a.speed;v.dmg=a.dmg;v.throwCd=a.powerCd;v.specialCd=a.specialCd;v.superMeter=a.superMeter;v.superReady=a.superReady;const walkMag=Math.hypot(a.moveVx||0,a.moveVy||0);v.vx=Math.abs(a.moveVx||0)>4?(a.moveVx||0):walkMag>4?(a.facing||1)*walkMag:0;v.state=(a.deadT>0||a.downT>0)?'ko':a.hurtT>0?'hurt':a.guard?'defend':a.attackT>0?(a.actionKind==='special'?'special':'throw'):!a.onGround?'air':walkMag>4?'walk':'idle';v.stateT=(v.stateT||0)+.016;v.animT=(v.animT||0)+.016;v.walkT=(v.walkT||0)+walkMag*.0005;v.proMove=a.proMove;v.ktrakAvatarT=a.avatarT;v.ktrakAvatarIntroT=a.avatarIntroT;v.laranjaCombo=a.sequence?.kind==='laranjaCombo'?{t:a.sequence.t}:null;v.laranjaFlash=a.sequence?.kind==='laranjaSuper'?{phase:a.sequence.next%3}:null;v.ytiriInvulnT=a.invulnPowerT;v.grizzLaserT=a.attackT&&a.id==='grizz'?.12:0}
function drawFallback(ctx,a){ctx.fillStyle=a.color||'#fff';ctx.fillRect(-20,-90,40,60);ctx.fillStyle='#e5b18d';ctx.beginPath();ctx.arc(0,-108,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#111827';ctx.fillRect(-17,-30,11,30);ctx.fillRect(6,-30,11,30)}
