function drawChronopause(ctx,g){if(g.enemyTimeStop<=0)return;const pulse=.04+.025*Math.sin(now()*8);ctx.save();ctx.fillStyle=`rgba(71,210,255,${pulse})`;ctx.fillRect(0,0,W,H);ctx.strokeStyle='rgba(160,240,255,.15)';ctx.lineWidth=1;for(let x=18;x<W;x+=72){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x-34,H);ctx.stroke()}for(const e of [...g.enemies,g.boss].filter(Boolean)){if(e.deadT>0)continue;const y=depthY(e.lane)-58*scaleAt(e.lane);ctx.strokeStyle='rgba(150,240,255,.72)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(e.x,y,42*scaleAt(e.lane)+Math.sin(now()*5)*3,0,Math.PI*2);ctx.stroke()}ctx.restore()}
