function drawRuins(){const g=ruinsGame;if(!g)return;const ctx=g.ctx;ctx.save();if(g.shake>0)ctx.translate((Math.random()-.5)*g.shake,(Math.random()-.5)*g.shake);drawBackground(ctx,g);for(const h of (g.hazards||[]).sort((a,b)=>a.lane-b.lane))drawHazard(ctx,h);for(const z of g.areas.sort((a,b)=>a.lane-b.lane))drawArea(ctx,z);const scene=[...(g.props||[]).filter(p=>!p.dead).map(p=>({kind:'prop',lane:p.lane,obj:p})),...(g.items||[]).map(it=>({kind:'item',lane:it.lane,obj:it}))];const actors=[...g.enemies.filter(e=>e.deadT>0||e.hits<e.maxHits)];if(g.boss)actors.push(g.boss);for(const p of (g.players||[g.player]))actors.push(p);for(const a of actors)scene.push({kind:'actor',lane:a.lane,obj:a});scene.sort((a,b)=>a.lane-b.lane);for(const s of scene){if(s.kind==='actor')drawActor(ctx,s.obj);else if(s.kind==='prop')drawProp(ctx,s.obj);else drawItem(ctx,s.obj)}for(const q of g.projectiles.sort((a,b)=>a.lane-b.lane))drawProjectile(ctx,q);for(const f of g.fx.sort((a,b)=>a.lane-b.lane))drawFx(ctx,f);drawChronopause(ctx,g);drawConfetti(ctx,g);drawBanner(ctx,g);ctx.restore()}
function ruinsLoop(t){const g=ruinsGame;if(!g)return;const dt=Math.min(.034,Math.max(0,(t-g.last)/1000));g.last=t;if(g.online&&!g.authoritative)ruinsSendGuestInput(t);updateRuins(dt);if(g.online&&g.authoritative)ruinsSendState(t);drawRuins();g.raf=requestAnimationFrame(ruinsLoop)}
function showRuinsCompleteOverlay(g,isClient=false){
  document.querySelector('.ruins-complete')?.remove();const ov=document.createElement('div');ov.className='ruins-complete';const confetti=Array.from({length:90},(_,i)=>`<i style="left:${(i*37)%100}%;--h:${(i*47)%360};--d:${3.2+(i%7)*.22}s;--delay:${-(i%13)*.22}s;--x:${-120+(i%9)*30}px;--r:${(i*57)%360}deg"></i>`).join('');ov.innerHTML=`<div class="ruins-confetti">${confetti}</div><div class="ruins-complete-card"><div class="ruins-complete-kicker">MISSÃO CONCLUÍDA${g?.online?' · DUPLA P2P':''}</div><div class="ruins-complete-title">VOCÊS COMPLETARAM<br>O MODO RUÍNAS</div><div class="ruins-complete-rojo">🔓 ROJO RECUPEROU A LIBERDADE!</div><p style="color:#aebbd0;max-width:650px;margin:0 auto">${g?.online?'HOST e CLIENT receberam a premiação completa.':'A missão foi concluída.'}</p><div class="ruins-complete-rewards"><div><b>10.000</b><span>GOLD</span></div><div><b>1.000</b><span>VANDAIS</span></div><div><b>70</b><span>PSY</span></div></div><div class="ruins-complete-actions">${g?.online?'':'<button id="ruins-complete-replay" class="btn big">↻ JOGAR NOVAMENTE</button>'}<button id="ruins-complete-modes" class="btn big">⚔️ VOLTAR AOS MODOS</button></div></div>`;document.body.appendChild(ov);document.getElementById('ruins-complete-replay')?.addEventListener('click',()=>{const id=g.selected.id,d=g.difficulty;ov.remove();ruinsCheckpoint=null;startRuins(id,{difficulty:d,coop:g.coop,p2Id:g.p2?.id})});document.getElementById('ruins-complete-modes').onclick=()=>{ov.remove();stopRuins();closeRuinsNetwork();renderModes()}}
function completeRuins(){const g=ruinsGame;if(!g)return;const token=g.sessionToken||('ruins-local-'+Date.now().toString(36));grantRuinsReward(token,REWARD);if(g.online&&g.authoritative&&ruinsNet?.role==='host')ruinsNetBroadcast({type:'reward',token,reward:REWARD});showRuinsCompleteOverlay(g,false)}
window.addEventListener('keydown',e=>{
  if(!isRuinsScreen())return;if(screen==='ruins-p2p-lobby'&&e.key==='Escape'){e.preventDefault();closeRuinsNetwork();renderRuinsSelect();return}if(screen==='ruins-select'&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();renderModes();return}if(screen!=='ruins-play'||!ruinsGame)return;
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','Numpad0'].includes(e.code))e.preventDefault();
  if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(ruinsGame.online){showNotice('P2P ONLINE · PAUSA DESATIVADA',1.1);return}ruinsGame.paused=!ruinsGame.paused;document.getElementById('ruins-pause')?.classList.toggle('show',ruinsGame.paused);if(!ruinsGame.paused)ruinsGame.last=performance.now();return}
  if(e.repeat)return;keys.add(e.code);const g=ruinsGame,p=g.player,p2=g.p2;
  if(g.online&&!g.authoritative){const action={KeyJ:'power',KeyI:'punch',KeyO:'kick',KeyG:'hook',KeyL:'super',KeyH:'extra',KeyU:'extra1',KeyP:'extra2',Space:'jump',KeyQ:'dodge'}[e.code];if(action)ruinsSendAction(action);return}
  const isP2Dir=g.coop&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code),isP1Dir=['KeyA','KeyD','KeyW','KeyS'].includes(e.code)||(!g.coop&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code));
  if(isP1Dir||isP2Dir){const who=isP2Dir?p2:p,group=e.code==='KeyA'||e.code==='ArrowLeft'?'left':e.code==='KeyD'||e.code==='ArrowRight'?'right':e.code==='KeyW'||e.code==='ArrowUp'?'up':'down',key=(who?.playerIndex||1)+':'+group,t=performance.now();if(who&&t-(g.lastTap[key]||0)<270){who.runT=.72;who.runDir=group==='left'?-1:group==='right'?1:0;showNotice(who.id==='laranja'?`⚡ ${who.name.toUpperCase()} · HIPERVELOCIDADE`:`${who.name.toUpperCase()} · CORRIDA`,.38)}g.lastTap[key]=t;if(who)rememberRuinsDir(who,group)}
  const c1=mappedRuinsActionCode(p,e.code,false),c2=p2?mappedRuinsActionCode(p2,e.code,true):e.code;
  if(c1==='KeyJ'){const tech=requestedRuinsMove(p);if(tech)melee(p,tech);else usePower(p)}else if(c1==='KeyI')melee(p,'punch');else if(c1==='KeyO')melee(p,'kick');else if(c1==='KeyG')melee(p,'uppercut');else if(c1==='KeyK'&&p.id==='klopp'&&p.copyId&&p.copyT>0){p.kloppCopyLockT=.24;p.powerCd=0;usePower(p,{forceId:p.copyId});p.powerCd=Math.max(p.powerCd,.55)}else if(c1==='KeyL')useSuper(p);else if(e.code==='KeyH')cycleUtility(p);else if(e.code==='KeyU')lkughRuinsExtra(p,'stars');else if(e.code==='KeyP')lkughRuinsExtra(p,'blackhole');else if(e.code==='Space')jumpActor(p);else if(c1==='KeyQ')playerDodge(p);
  if(p2){if(c2==='Numpad1'){const tech=requestedRuinsMove(p2);if(tech)melee(p2,tech);else usePower(p2)}else if(c2==='Numpad5')melee(p2,'punch');else if(c2==='Numpad6')melee(p2,'kick');else if(c2==='Numpad4')melee(p2,'uppercut');else if(c2==='Numpad2'&&p2.id==='klopp'&&p2.copyId&&p2.copyT>0){p2.kloppCopyLockT=.24;p2.powerCd=0;usePower(p2,{forceId:p2.copyId});p2.powerCd=Math.max(p2.powerCd,.55)}else if(c2==='Numpad3')useSuper(p2);else if(e.code==='Numpad9')cycleUtility(p2);else if(e.code==='Numpad8')lkughRuinsExtra(p2,'stars');else if(e.code==='NumpadDecimal')lkughRuinsExtra(p2,'blackhole');else if(e.code==='Numpad0')jumpActor(p2);else if(c2==='Numpad7')playerDodge(p2)}
},true);
